  "Sorry — we couldn't delete your account just now. Please try again, or email support@financelog.app.": "Desculpe, não conseguimos excluir sua conta agora. Tente de novo ou escreva para support@financelog.app.",
  "pnl.h1": "Seu diário de trades completo,<br><span class=\"pw-g\">desbloqueado.</span>",
  "Everything you need to track every trade — private, synced only to your own account.": "Tudo o que você precisa para acompanhar cada trade. Privado, sincronizado só com a sua conta.",
  "pnl.b1": "Registre trades ilimitados com <b>P&amp;L automático</b>",
  "pnl.b2": "Taxa de acerto, fator de lucro e <b>curva de patrimônio</b>",
