  "pnl.b4": "<b>Sincronização</b> segura entre seus aparelhos",
  "pnl.b5": "<b>Privado por natureza</b>: só você vê",
  "pnl.b6": "Exporte seus trades para <b>CSV</b>, ótimo para o imposto de renda",
  "7 days free, then billed yearly": "7 dias grátis, depois cobrança anual",
  "7 days free, then billed monthly": "7 dias grátis, depois cobrança mensal",
  "Start 7-day free trial": "Começar 7 dias grátis",
  "Subscribe – {0}/year": "Assinar: {0}/ano",
  "Subscribe – {0}/month": "Assinar: {0}/mês",
  "Free for 7 days, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Settings. Payment is charged to your Apple Account.": "Grátis por 7 dias; depois, o plano escolhido é renovado automaticamente. Cancele quando quiser, pelo menos 24 horas antes do fim do teste, nos Ajustes. O pagamento é cobrado na sua Conta Apple.",
  "Free for 7 days, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Google Play settings. Payment is charged to your Google Play account.": "Grátis por 7 dias; depois, o plano escolhido é renovado automaticamente. Cancele quando quiser, pelo menos 24 horas antes do fim do teste, nas configurações do Google Play. O pagamento é cobrado na sua conta do Google Play.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Cobrança de {0} por ano a partir de hoje, com renovação automática. Cancele quando quiser nos Ajustes. O pagamento é cobrado na sua Conta Apple.",
  "Billed {0} per month starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Cobrança de {0} por mês a partir de hoje, com renovação automática. Cancele quando quiser nos Ajustes. O pagamento é cobrado na sua Conta Apple.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Google Play settings. Payment is charged to your Google Play account.": "Cobrança de {0} por ano a partir de hoje, com renovação automática. Cancele quando quiser nas configurações do Google Play. O pagamento é cobrado na sua conta do Google Play.",
  "Billed {0} per month starting today, renews automatically. Cancel anytime in Google Play settings. Payment is charged to your Google Play account.": "Cobrança de {0} por mês a partir de hoje, com renovação automática. Cancele quando quiser nas configurações do Google Play. O pagamento é cobrado na sua conta do Google Play.",
