  "Cancel": "Отмена",
  "Delete forever": "Удалить навсегда",
  "Your account and all your data have been permanently deleted.": "Аккаунт и все данные удалены навсегда.",
  "Sorry — we couldn't delete your account just now. Please try again, or email support@financelog.app.": "Извините, сейчас не удалось удалить аккаунт. Попробуйте ещё раз или напишите на support@financelog.app.",
  "pnl.h1": "Весь торговый журнал<br><span class=\"pw-g\">без ограничений.</span>",
  "Everything you need to track every trade — private, synced only to your own account.": "Всё, чтобы вести учёт каждой сделки. Конфиденциально, синхронизируется только с вашим аккаунтом.",
  "pnl.b1": "Неограниченно сделок с <b>автоматическим P&amp;L</b>",
  "pnl.b2": "Винрейт, профит-фактор и <b>кривая капитала</b>",
  "pnl.b3": "Позиции, сделки, пополнения и выводы",
  "pnl.b4": "Надёжная <b>синхронизация</b> между устройствами",
  "pnl.b5": "<b>Конфиденциально</b>: видите только вы",
  "pnl.b6": "Экспорт сделок в <b>CSV</b>, удобно для налогов",
  "7 days free, then billed yearly": "7 дней бесплатно, затем оплата за год",
  "7 days free, then billed monthly": "7 дней бесплатно, затем оплата помесячно",
  "Start 7-day free trial": "Начать 7 дней бесплатно",
  "Subscribe – {0}/year": "Подписаться: {0}/год",
  "Subscribe – {0}/month": "Подписаться: {0}/мес.",
  "Free for 7 days, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Settings. Payment is charged to your Apple Account.": "Бесплатно 7 дней, затем выбранный план продлевается автоматически. Отменить можно в любой момент, не позднее чем за 24 часа до конца пробного периода, в Настройках. Оплата списывается с вашего Аккаунта Apple.",
  "Free for 7 days, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Google Play settings. Payment is charged to your Google Play account.": "Бесплатно 7 дней, затем выбранный план продлевается автоматически. Отменить можно в любой момент, не позднее чем за 24 часа до конца пробного периода, в настройках Google Play. Оплата списывается с вашего аккаунта Google Play.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Списание {0} в год с сегодняшнего дня, продление автоматическое. Отменить можно в любой момент в Настройках. Оплата списывается с вашего Аккаунта Apple.",
  "Billed {0} per month starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Списание {0} в месяц с сегодняшнего дня, продление автоматическое. Отменить можно в любой момент в Настройках. Оплата списывается с вашего Аккаунта Apple.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Google Play settings. Payment is charged to your Google Play account.": "Списание {0} в год с сегодняшнего дня, продление автоматическое. Отменить можно в любой момент в настройках Google Play. Оплата списывается с вашего аккаунта Google Play.",
  "Billed {0} per month starting today, renews automatically. Cancel anytime in Google Play settings. Payment is charged to your Google Play account.": "Списание {0} в месяц с сегодняшнего дня, продление автоматическое. Отменить можно в любой момент в настройках Google Play. Оплата списывается с вашего аккаунта Google Play.",
  "A P&L Pro subscription is required to log your own trades.": "Чтобы записывать свои сделки, нужна подписка P&L Pro.",
