  "Your account and all your data have been permanently deleted.": "Tu cuenta y todos tus datos se han eliminado para siempre.",
  "Sorry — we couldn't delete your account just now. Please try again, or email support@financelog.app.": "Lo sentimos, no pudimos eliminar tu cuenta en este momento. Inténtalo de nuevo o escribe a support@financelog.app.",
  "pnl.h1": "Tu diario de trading completo,<br><span class=\"pw-g\">desbloqueado.</span>",
  "Everything you need to track every trade — private, synced only to your own account.": "Todo lo que necesitas para seguir cada operación. Privado, sincronizado solo con tu propia cuenta.",
  "pnl.b1": "Registra operaciones ilimitadas con <b>P&amp;L automático</b>",
  "pnl.b2": "Tasa de acierto, factor de beneficio y <b>curva de capital</b>",
  "pnl.b3": "Posiciones, operaciones, depósitos y retiros",
  "pnl.b4": "<b>Sincronización</b> segura entre tus dispositivos",
  "pnl.b5": "<b>Privado por diseño</b>: solo tú lo ves",
  "pnl.b6": "Exporta tus operaciones a <b>CSV</b>, ideal para los impuestos",
  "7 days free, then billed yearly": "7 días gratis, luego facturación anual",
  "7 days free, then billed monthly": "7 días gratis, luego facturación mensual",
  "Start 7-day free trial": "Empezar prueba gratis de 7 días",
  "Subscribe – {0}/year": "Suscribirse: {0}/año",
  "Subscribe – {0}/month": "Suscribirse: {0}/mes",
  "Free for 7 days, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Settings. Payment is charged to your Apple Account.": "Gratis durante 7 días; después, el plan elegido se renueva automáticamente. Cancela cuando quieras, al menos 24 horas antes de que termine la prueba, en Ajustes. El pago se cobra en tu cuenta de Apple.",
  "Free for 7 days, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Google Play settings. Payment is charged to your Google Play account.": "Gratis durante 7 días; después, el plan elegido se renueva automáticamente. Cancela cuando quieras, al menos 24 horas antes de que termine la prueba, en la configuración de Google Play. El pago se cobra en tu cuenta de Google Play.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Cobro de {0} al año desde hoy, con renovación automática. Cancela cuando quieras en Ajustes. El pago se cobra en tu cuenta de Apple.",
  "Billed {0} per month starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Cobro de {0} al mes desde hoy, con renovación automática. Cancela cuando quieras en Ajustes. El pago se cobra en tu cuenta de Apple.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Google Play settings. Payment is charged to your Google Play account.": "Cobro de {0} al año desde hoy, con renovación automática. Cancela cuando quieras en la configuración de Google Play. El pago se cobra en tu cuenta de Google Play.",
  "Billed {0} per month starting today, renews automatically. Cancel anytime in Google Play settings. Payment is charged to your Google Play account.": "Cobro de {0} al mes desde hoy, con renovación automática. Cancela cuando quieras en la configuración de Google Play. El pago se cobra en tu cuenta de Google Play.",
  "A P&L Pro subscription is required to log your own trades.": "Se necesita una suscripción a P&L Pro para registrar tus propias operaciones.",
