  "You closed {0} trades: {1} winners, profit factor {2}, and on average each trade made {3}.": "Du hast {0} Trades geschlossen: {1} Gewinner, Profitfaktor {2}, und im Schnitt brachte jeder Trade {3}.",
  "Your P&L Pro subscription ended. One tap helps us improve. Logging trades stays free.": "Dein P&L Pro-Abo ist abgelaufen. Ein Tippen hilft uns, besser zu werden. Trades eintragen bleibt kostenlos.",
  "Your average loss ({0}) is bigger than your average win ({1}). Cutting losers sooner is your biggest lever.": "Dein Ø-Verlust ({0}) ist größer als dein Ø-Gewinn ({1}). Verluste früher zu schließen, ist dein größter Hebel.",
