  "pw.b4": "Feste monatliche Rechnungen, <b>automatisch</b>",
  "pw.b5": "Exportiere deine Daten als <b>CSV</b>, ideal für die Steuererklärung",
  "pw.b6": "<b>Privat von Grund auf</b>: nur du siehst es",
