  "Free for 7 days, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Google Play settings. Payment is charged to your Google Play account.": "7 Tage kostenlos, danach verlängert sich dein gewähltes Abo automatisch. Du kannst jederzeit kündigen, spätestens 24 Stunden vor Ende des Testzeitraums, in den Google Play-Einstellungen. Die Zahlung wird deinem Google Play-Konto belastet.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Ab heute werden {0} pro Jahr berechnet, das Abo verlängert sich automatisch. Du kannst jederzeit in den Einstellungen kündigen. Die Zahlung wird deinem Apple Account belastet.",
  "Billed {0} per month starting today, renews automatically. Cancel anytime in Settings. Payment is charged to your Apple Account.": "Ab heute werden {0} pro Monat berechnet, das Abo verlängert sich automatisch. Du kannst jederzeit in den Einstellungen kündigen. Die Zahlung wird deinem Apple Account belastet.",
  "Billed {0} per year starting today, renews automatically. Cancel anytime in Google Play settings. Payment is charged to your Google Play account.": "Ab heute werden {0} pro Jahr berechnet, das Abo verlängert sich automatisch. Du kannst jederzeit in den Google Play-Einstellungen kündigen. Die Zahlung wird deinem Google Play-Konto belastet.",
