 "pw.h1": "Tout votre budget,<br><span class=\"pw-g\">débloqué.</span>",
 "Everything you need to plan your money and track every day — private, synced only to your own account.": "Tout ce qu’il faut pour planifier votre argent et suivre chaque jour. Privé, synchronisé uniquement avec votre propre compte.",
 "pw.b1": "Revenus et dépenses par catégorie, <b>chaque mois</b>",
