 "Free for 1 week, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Settings. Payment is charged to your Apple Account.": "Gratuit pendant 1 semaine, puis l’offre choisie se renouvelle automatiquement. Annulez à tout moment, au moins 24 heures avant la fin de l’essai, dans Réglages. Le paiement est débité sur votre compte Apple.",
 "Free for 1 week, then your selected plan renews automatically. Cancel anytime, at least 24 hours before the trial ends, in Google Play settings. Payment is charged to your Google Play account.": "Gratuit pendant 1 semaine, puis l’offre choisie se renouvelle automatiquement. Annulez à tout moment, au moins 24 heures avant la fin de l’essai, dans les paramètres Google Play. Le paiement est débité sur votre compte Google Play.",
