/* How to use in Settings (Nov 21 2026) */
if (window.I18N_DICT && window.I18N_DICT.pt) Object.assign(window.I18N_DICT.pt, {"How to use": "Como usar", "Watch how it works": "Veja como funciona", "1 min, 6 steps": "1 min, 6 passos", "Step": "Passo", "Watch again": "Ver de novo", "Play": "Reproduzir", "Log every buy and sell in “Add a trade”: pick Bought or Sold, then the symbol, quantity and price.": "Registre cada compra e venda em “Adicionar trade”: escolha Compra ou Venda e depois o ticker, a quantidade e o preço.", "Your holdings update on their own. Tap “Live prices” for today’s value.": "Suas posições se atualizam sozinhas. Toque em “Preços ao vivo” para ver o valor de hoje.", "Each sale books its realized P&L: the dashboard, equity curve, monthly chart and calendar fill in automatically.": "Cada venda registra o seu P&L realizado: o painel, a curva de patrimônio, o gráfico mensal e o calendário se preenchem sozinhos.", "Tap ⤢ on a trade to tag its setup and mistakes, and your trading report shows what works.": "Toque em ⤢ em um trade para marcar o setup e os erros, e o seu relatório de trading mostra o que funciona.", "Coming from a broker? “Import CSV” brings in your history (Pro).": "Vem de uma corretora? “Importar CSV” traz o seu histórico (Pro).", "Switch years with the year picker, and start a new one with “+ Year”.": "Troque de ano no seletor de ano e comece um novo com “＋ Ano”."});
if (window.I18N_DICT && window.I18N_DICT.ru) Object.assign(window.I18N_DICT.ru, {"How to use": "Как пользоваться", "Watch how it works": "Посмотрите, как это работает", "1 min, 6 steps": "1 мин, 6 шагов", "Step": "Шаг", "Watch again": "Смотреть снова", "Play": "Воспроизвести", "Log every buy and sell in “Add a trade”: pick Bought or Sold, then the symbol, quantity and price.": "Записывайте каждую покупку и продажу в «Добавить сделку»: выберите «Покупка» или «Продажа», затем тикер, количество и цену.", "Your holdings update on their own. Tap “Live prices” for today’s value.": "Ваши позиции обновляются сами. Нажмите «Цены онлайн», чтобы увидеть сегодняшнюю стоимость.", "Each sale books its realized P&L: the dashboard, equity curve, monthly chart and calendar fill in automatically.": "Каждая продажа фиксирует реализованный P&L: панель, кривая капитала, месячный график и календарь заполняются автоматически.", "Tap ⤢ on a trade to tag its setup and mistakes, and your trading report shows what works.": "Нажмите ⤢ у сделки, чтобы отметить сетап и ошибки, а ваш торговый отчёт покажет, что работает.", "Coming from a broker? “Import CSV” brings in your history (Pro).": "Переходите от брокера? «Импорт CSV» перенесёт вашу историю (Pro).", "Switch years with the year picker, and start a new one with “+ Year”.": "Переключайте годы в выборе года, а новый год начинайте кнопкой «＋ Год»."});
if (window.I18N_DICT && window.I18N_DICT.es) Object.assign(window.I18N_DICT.es, {"How to use": "Cómo se usa", "Watch how it works": "Mira cómo funciona", "1 min, 6 steps": "1 min, 6 pasos", "Step": "Paso", "Watch again": "Ver de nuevo", "Play": "Reproducir", "Log every buy and sell in “Add a trade”: pick Bought or Sold, then the symbol, quantity and price.": "Registra cada compra y venta en «Añadir operación»: elige Compra o Venta y luego el símbolo, la cantidad y el precio.", "Your holdings update on their own. Tap “Live prices” for today’s value.": "Tus posiciones se actualizan solas. Toca «Precios en vivo» para ver el valor de hoy.", "Each sale books its realized P&L: the dashboard, equity curve, monthly chart and calendar fill in automatically.": "Cada venta registra su P&L realizado: el panel, la curva de capital, el gráfico mensual y el calendario se completan solos.", "Tap ⤢ on a trade to tag its setup and mistakes, and your trading report shows what works.": "Toca ⤢ en una operación para etiquetar su setup y sus errores, y tu informe de trading te muestra lo que funciona.", "Coming from a broker? “Import CSV” brings in your history (Pro).": "¿Vienes de un bróker? «Importar CSV» trae tu historial (Pro).", "Switch years with the year picker, and start a new one with “+ Year”.": "Cambia de año con el selector de año y empieza uno nuevo con «＋ Año»."});
if (window.I18N_DICT && window.I18N_DICT.de) Object.assign(window.I18N_DICT.de, {"How to use": "Anleitung", "Watch how it works": "So funktioniert es", "1 min, 6 steps": "1 Min., 6 Schritte", "Step": "Schritt", "Watch again": "Nochmal ansehen", "Play": "Abspielen", "Log every buy and sell in “Add a trade”: pick Bought or Sold, then the symbol, quantity and price.": "Erfasse jeden Kauf und Verkauf unter „Trade hinzufügen“: Wähle Gekauft oder Verkauft, dann Symbol, Stückzahl und Preis.", "Your holdings update on their own. Tap “Live prices” for today’s value.": "Deine Bestände aktualisieren sich von selbst. Tippe auf „Live-Kurse“ für den heutigen Wert.", "Each sale books its realized P&L: the dashboard, equity curve, monthly chart and calendar fill in automatically.": "Jeder Verkauf bucht seinen realisierten P&L: Übersicht, Equity-Kurve, Monatsdiagramm und Kalender füllen sich automatisch.", "Tap ⤢ on a trade to tag its setup and mistakes, and your trading report shows what works.": "Tippe bei einem Trade auf ⤢, um Setup und Fehler zu markieren. Dein Trading-Bericht zeigt, was funktioniert.", "Coming from a broker? “Import CSV” brings in your history (Pro).": "Du kommst von einem Broker? „CSV importieren“ holt deine Historie (Pro).", "Switch years with the year picker, and start a new one with “+ Year”.": "Wechsle das Jahr in der Jahresauswahl und beginne ein neues mit „＋ Jahr“."});
if (window.I18N_DICT && window.I18N_DICT.ja) Object.assign(window.I18N_DICT.ja, {"How to use": "使い方", "Watch how it works": "使い方を動画で見る", "1 min, 6 steps": "1分・6ステップ", "Step": "ステップ", "Watch again": "もう一度見る", "Play": "再生", "Log every buy and sell in “Add a trade”: pick Bought or Sold, then the symbol, quantity and price.": "「トレードを追加」で売買をすべて記録します。「買い」か「売り」を選び、銘柄、数量、価格を入力します。", "Your holdings update on their own. Tap “Live prices” for today’s value.": "保有銘柄は自動で更新されます。「リアルタイム価格」をタップすると今日の評価額が表示されます。", "Each sale books its realized P&L: the dashboard, equity curve, monthly chart and calendar fill in automatically.": "売却するたびに確定損益が記録され、ダッシュボード、資産曲線、月間チャート、カレンダーが自動で更新されます。", "Tap ⤢ on a trade to tag its setup and mistakes, and your trading report shows what works.": "トレードの⤢をタップしてセットアップとミスをタグ付けすると、トレードレポートで何がうまくいっているかが分かります。", "Coming from a broker? “Import CSV” brings in your history (Pro).": "証券会社から移行する場合は、「CSVをインポート」で履歴を取り込めます（Pro）。", "Switch years with the year picker, and start a new one with “+ Year”.": "年は年の選択で切り替え、新しい年は「＋ 年」で始められます。"});
if (window.I18N_DICT && window.I18N_DICT.ko) Object.assign(window.I18N_DICT.ko, {"How to use": "사용 방법", "Watch how it works": "사용 방법 영상 보기", "1 min, 6 steps": "1분, 6단계", "Step": "단계", "Watch again": "다시 보기", "Play": "재생", "Log every buy and sell in “Add a trade”: pick Bought or Sold, then the symbol, quantity and price.": "‘거래 추가’에서 모든 매수와 매도를 기록하세요. 매수 또는 매도를 고른 뒤 종목, 수량, 가격을 입력합니다.", "Your holdings update on their own. Tap “Live prices” for today’s value.": "보유 종목은 자동으로 업데이트됩니다. ‘실시간 가격’을 누르면 오늘의 가치를 볼 수 있습니다.", "Each sale books its realized P&L: the dashboard, equity curve, monthly chart and calendar fill in automatically.": "매도할 때마다 실현 손익이 기록되고 대시보드, 자산 곡선, 월별 차트, 캘린더가 자동으로 채워집니다.", "Tap ⤢ on a trade to tag its setup and mistakes, and your trading report shows what works.": "거래의 ⤢를 눌러 셋업과 실수를 태그하면 내 매매 리포트가 효과 있는 방법을 보여 줍니다.", "Coming from a broker? “Import CSV” brings in your history (Pro).": "증권사에서 옮겨 오시나요? ‘CSV 가져오기’로 거래 내역을 불러옵니다(Pro).", "Switch years with the year picker, and start a new one with “+ Year”.": "연도 선택에서 연도를 바꾸고, ‘＋ 연도’로 새 연도를 시작하세요."});
if (window.I18N_DICT && window.I18N_DICT.fr) Object.assign(window.I18N_DICT.fr, {"How to use": "Mode d’emploi", "Watch how it works": "Voir comment ça marche", "1 min, 6 steps": "1 min, 6 étapes", "Step": "Étape", "Watch again": "Revoir", "Play": "Lire", "Log every buy and sell in “Add a trade”: pick Bought or Sold, then the symbol, quantity and price.": "Notez chaque achat et chaque vente dans « Ajouter un trade » : choisissez Acheté ou Vendu, puis le symbole, la quantité et le prix.", "Your holdings update on their own. Tap “Live prices” for today’s value.": "Vos positions se mettent à jour toutes seules. Touchez « Prix en direct » pour leur valeur du jour.", "Each sale books its realized P&L: the dashboard, equity curve, monthly chart and calendar fill in automatically.": "Chaque vente enregistre son P&L réalisé : le tableau de bord, la courbe de capital, le graphique mensuel et le calendrier se remplissent automatiquement.", "Tap ⤢ on a trade to tag its setup and mistakes, and your trading report shows what works.": "Touchez ⤢ sur un trade pour indiquer son setup et ses erreurs, et votre rapport de trading montre ce qui marche.", "Coming from a broker? “Import CSV” brings in your history (Pro).": "Vous venez d’un courtier ? « Importer CSV » récupère votre historique (Pro).", "Switch years with the year picker, and start a new one with “+ Year”.": "Changez d’année avec le sélecteur d’année, et commencez-en une nouvelle avec « ＋ Année »."});
